/** Adds what the demo kit gained after it was first saved (links to brand tools, the guide, merch). Null when up to date. */
export function patchKit(kit: any): any | null {
  const v = kit?.demo_kit_v || 1;
  if (v >= SUPERPLANE_KIT.demo_kit_v) return null;
  // v6-7: the guide rebuilt with sharp visuals and live text, the case film and videos, backgrounds; the guide is not
  // edited in the app, so the saved one is replaced
  return { ...kit, links: kit.links?.length ? kit.links : SUPERPLANE_KIT.links, guide: SUPERPLANE_KIT.guide, videos: SUPERPLANE_KIT.videos, backgrounds: SUPERPLANE_KIT.backgrounds || kit.backgrounds, demo_kit_v: SUPERPLANE_KIT.demo_kit_v };
}
